// Dependency-free contract definitions. JSON copies are generated by export-schemas.mjs.
const number={type:'number'}, text={type:'string',minLength:1,maxLength:2048};
const object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});
const list=(items,minItems=0,maxItems=1000000)=>({type:'array',items,minItems,maxItems});
const vec=list(number,3,3), matrix=list(vec,3,3);
const source=object({source:text,assumptions:list(text,0,500)});
const pose=object({xyz_m:vec,rpy_rad:vec});
const component=object({name:text,mass_kg:{type:'number',minimum:0,maximum:1e9},com_m:vec,inertia_kg_m2:matrix,provenance:source},['name','mass_kg','com_m','provenance']);
const joint=object({id:text,name:text,type:{enum:['revolute','prismatic','fixed']},origin:pose,axis:vec,limits:list(number,2,2),components:list(component,0,100)},['id','name','type','origin']);
const payload=object({mass_kg:{type:'number',minimum:0,maximum:1e9},com_in_tip_m:vec,provenance:source});
const header=name=>({schema_name:{const:name},schema_version:{const:'1.0'}});
const model=object({...header('arm-design-model'),name:text,joints:list(joint,1,64),tip:pose,base_in_world:pose,gravity_world_m_s2:vec,payload,provenance:source},['schema_name','schema_version','name','joints','tip','provenance']);
const request=object({...header('arm-analysis-request'),design_model:model,options:{type:'object'} });
const trajectory=object({...header('arm-trajectory'),joint_ids:list(text,1,64),joint_types:list({enum:['revolute','prismatic']},1,64),samples:list(object({time_s:{type:'number',minimum:0},q:list(number,1,64),dq:list(number,1,64),ddq:list(number,1,64),phase_id:text}),1),provenance:source});
const trace=object({...header('arm-joint-trace'),joint_ids:list(text,1,64),samples:list(object({time_s:{type:'number',minimum:0},joint_id:text,phase_id:text,q:number,dq:number,ddq:{type:['number','null']},effort:{type:['number','null']},effort_semantics:{enum:['inverse_dynamics','drive_output','solver_projected','unavailable']},effort_unit:{enum:['Nm','N']},interface_wrench:{anyOf:[{type:'null'},object({force_N:vec,moment_Nm:vec,frame:text,point_m:vec})]},quality_flags:list(text)}),1),provenance:source});
const caseSpec=object({...header('arm-case'),name:text,phases:list(object({id:text,kind:{enum:['hold','move','wait']},duration_s:{type:'number',exclusiveMinimum:0},q_target:list(number,1,64)}),1,1000),repetitions:{type:'integer',minimum:1},provenance:source});
const manifest=object({...header('arm-run-manifest'),run_id:text,skill:text,engine_version:text,code_revision:text,source_backend:text,status:{enum:['completed','failed','cancelled','partial']},input_sha256:{type:'string',pattern:'^[a-f0-9]{64}$'},model_sha256:{type:'string',pattern:'^[a-f0-9]{64}$'},assumptions:list(text),artifacts:list(object({path:text,sha256:{type:'string',pattern:'^[a-f0-9]{64}$'}}))});
export const schemas={'design-model':model,'analysis-request':request,trajectory,'joint-trace':trace,case:caseSpec,'run-manifest':manifest};
